def solve():
	(n, p) = read_int()
	lsorce = read_list()
	li = [(int(i), p) for (p, i) in enumerate(lsorce)]
	li.sort()
	vis = [False for i in li]
	ans = 0
	ato = n - 1
	for (val, pid) in li:
		if val >= p:
			break
		else:
			if vis[pid]:
				continue
			ll = pid
			rr = pid
			while ll < len(lsorce) - 1 and (not vis[ll]) and (lsorce[ll + 1] % val == 0):
				ll += 1
			while rr >= 1 and (not vis[rr]) and (lsorce[rr - 1] % val == 0):
				rr -= 1
			for ppp in range(rr, ll + 1):
				vis[ppp] = True
			ctr = ll - rr + 1
			ato -= ctr - 1
			ans += val * (ctr - 1)
	ans += ato * p
	print(ans)
t = int(input())
for ti in range(t):
	solve()
